 *
 * @returns {Object} Payload accepted by `normalizeGraphPayload`.
 *
 * @example
 * const { rows } = normalizeGraphPayload(createMockGraph())
 */
export function createMockGraph() {
  return {
    mock: true,
    default_branch: 'upstream/main',
    active_branch: 'ardalis/scaling-scenarios',
    branches: MOCK_COMMITS.flatMap((commit) =>
      (commit.refs || []).map((ref) => ({ name: ref.name, type: ref.type, commit: commit.hash }))
    ),
    commits: MOCK_COMMITS.map((commit) => ({ ...commit }))
  }
}

/**
 * Minimal unified diff, used when a commit/file diff is not available.
 *
 * @param {string} path - Repository relative file path.
 * @returns {string} Unified patch.
 */
export function createMockFileDiff(path = 'aspnetcore/toc.yml') {
  return [
    `diff --git a/${path} b/${path}`,
    `--- a/${path}`,
    `+++ b/${path}`,
    '@@ -1,4 +1,6 @@',
    ' # Documentation',
    ' ',
    '- [Old section](old-section.md)',
    '+- [Scaling apps](scaling/index.md)',
    '+- [Hosting apps](hosting/index.md)',
    ' ',
    ' [Contributing](../CONTRIBUTING.md)'
  ].join('\n')
}

/**
 * Mock commit detail (files changed), used until the commit endpoint exists.
 *
 * @param {Object} [commit] - Commit the detail belongs to.
 * @returns {Object} Commit detail.
 */
export function createMockCommitDetail(commit = {}) {
  const files = [
    { path: 'aspnetcore/toc.yml', status: 'modified', additions: 12, deletions: 4 },
    { path: 'aspnetcore/security/gdpr.md', status: 'added', additions: 64, deletions: 0 },
    { path: 'aspnetcore/fundamentals/index.md', status: 'deleted', additions: 0, deletions: 21 }
  ].map((file) => ({ ...file, diff: createMockFileDiff(file.path) }))

  const additions = files.reduce((total, file) => total + file.additions, 0)
  const deletions = files.reduce((total, file) => total + file.deletions, 0)

  return {
    mock: true,
    commit: commit.hash || '',
    stat: `${files.length} file(s) changed, ${additions} insertions(+), ${deletions} deletions(-)`,
    total_additions: additions,
    total_deletions: deletions,
    files
  }
}

